import React from "react";
import { useNavigate } from "react-router-dom";
import './Bienvenida.css';

export default function Bienvenida() {
  const navigate = useNavigate();

  return (
    <div className="bienvenida-container">
      <header className="bienvenida-header">
        <h1>Bienvenido</h1>
        <div className="header-logo">
          <img src="/university-college-logo-circular-emblem.jpg" alt="Logo" />
        </div>
      </header>

      <div className="bienvenida-buttons">
        <button className="bienvenida-button" onClick={() => navigate("/administrativas")}>
          <img src="modulo-principal/public/Escuela_tec.jpg" alt="Administrativas" />
          <div className="button-overlay" />
          <div className="button-text">ADMINISTRATIVAS</div>
        </button>

        <div className="divider" />

        <button className="bienvenida-button" onClick={() => navigate("/ubicaciones")}>
          <img src="/modulo-principal/public/mapa_tec.png" alt="Ubicaciones" />
          <div className="button-overlay" />
          <div className="button-text">UBICACIONES</div>
        </button>
      </div>
    </div>
  );
}
